// Rotate through a bank of warm, culturally resonant check-in messages
// Alternates between English and Roman Urdu for engagement
const messages = [
  "Assalam-o-Alaikum! 🌸 Aaj kaisa feel ho raha hai? Koi baat karna ho toh main hoon yahan. 💙",
  "Good morning! ☀️ How are you feeling today? I'm here whenever you'd like to talk.",
  "Aaj ka din kaisa ja raha hai? Bohot saari zindagi ka bojh akele uthana padta hai — aap akele nahi hain. 💙",
  "Kya aaj aap apne aap ka khayal rakh rahe hain? 🌙 Thoda rest bhi zaroori hai.",
  "Hey, just checking in 💙 How has your week been? Big or small — I'm here to listen.",
  "Aaj ek chota sa sawaal: 1 se 10 tak, aaj aap khud ko kahan rakhenge? Seedha jawab dein — koi judgment nahi. 😊",
  "Kaisi neend aayi raat ko? Your rest matters. 🌙 Share karein agar kuch baat karni ho."
];

const sessionData = $input.first().json;
const randomIndex = Math.floor(Math.random() * messages.length);

return [{
  json: {
    session_id: sessionData.session_id,
    phone_number: sessionData.phone_number,
    message: messages[randomIndex],
    day_of_week: new Date().toLocaleDateString('en-US', { weekday: 'long' })
  }
}];

const result = $input.first().json;
console.log(`[Hamsafar Check-In] Sent to session ${$('Randomly Select Check-In Message').first().json.session_id} at ${new Date().toISOString()}`);
return [{ json: { status: 'sent', timestamp: new Date().toISOString() } }];
